          "claim": "Every abnormal POST /trips/left and trip_detail server span on ts-travel-service returns 500 with Error status."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-travel-service' AND message LIKE '%URI is not absolute%' GROUP BY ALL",
          "claim": "ts-travel-service throws IllegalArgumentException 'URI is not absolute' about 397 times in the incident window; none in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.span_name, c.span_name AS child, c.attr_status_code, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-service' AND p.span_name LIKE '%queryInfo%' GROUP BY ALL",
          "claim": "queryInfo fails after its DB child TripRepository.findAll succeeds, so the error is in application code, not the database."
        }
